## ============================================================================
## 01_dgp.R -- temporal generative process with admin-1, age-sex, and lambda
##             scenarios. Sourced by the run scripts; not run directly.
##
## Unit u = (district d) x (age-sex stratum s).  U = D x S units, T waves.
## simulate_population() returns latent truth + routine signal at unit level;
## the survey signal is generated by observe_survey() given a DISTRICT-level
## allocation (a survey fielded in a district observes all its strata).
## ============================================================================

## ---- lambda time-dynamics for one scenario --------------------------------
## returns a U x T matrix of the TIME-VARYING part added to the unit baseline.
lambda_dynamics <- function(scn, U, T, seed_off = 0) {
  dl <- matrix(0, U, T)
  if (scn$type == "constant") {
    ## nothing: offset constant over time
  } else if (scn$type == "drift") {
    slope <- rnorm(U, 0, scn$slope_sd)
    dl <- outer(slope, 0:(T - 1))
  } else if (scn$type == "shock") {
    dl[, scn$t0:T] <- scn$size                    # common structural break
  } else if (scn$type == "reshuffle") {
    om <- matrix(0, U, T)
    om[, 1] <- rnorm(U, 0, scn$sd_omega / sqrt(1 - scn$phi^2))
    for (t in 2:T) om[, t] <- scn$phi * om[, t - 1] + rnorm(U, 0, scn$sd_omega)
    dl <- om
  }
  dl
}

## ---- one synthetic country -------------------------------------------------
## Offset arguments (the defaults give the baseline DGP):
##   lambda_stratum_scale  multiplies the between-stratum spread about its mean
##   lambda_dist_sd        district-level offset deviation (transport failure)
##   lambda_prov_sd        between-province offset variation; 0 = none, and the
##                         draw is then skipped so the random-number stream is unchanged
simulate_population <- function(cfg, scenario = "drift", seed = NULL,
                                lambda_stratum_scale = 1,
                                lambda_dist_sd = cfg$lambda_dist_sd,
                                lambda_prov_sd = 0) {
  if (!is.null(seed)) set.seed(seed)
  G <- cfg$G; D <- cfg$D; S <- cfg$S; T <- cfg$T
  strata <- cfg$strata
  tt <- 0:(T - 1)

  ## --- index table: one row per unit (district x stratum) ------------------
  prov_of_d <- rep(seq_len(G), each = cfg$d_per_prov)
  idx <- expand.grid(d = seq_len(D), s = seq_len(S))
  idx$prov    <- prov_of_d[idx$d]
  idx$stratum <- strata$stratum[idx$s]
  idx$sex     <- strata$sex[idx$s]
  idx$age     <- strata$age[idx$s]
  U <- nrow(idx)

  ## --- province (admin-1) and district effects on logit-prevalence ---------
  prov_eff <- scale(seq_len(G))[, 1] * cfg$prov_spread      # ordered gradient
  prov_eff <- prov_eff + rnorm(G, 0, 0.10)
  dist_eff <- rnorm(D, 0, cfg$dist_sd)
  dist_aw  <- rnorm(D, 0, cfg$aware_dist_sd)

  ## --- prevalence & awareness over time, per unit --------------------------
  prev  <- aware <- matrix(NA, U, T)
  for (u in 1:U) {
    d <- idx$d[u]; st <- idx$stratum[u]
    p_base <- qlogis(cfg$prev0[[st]]) + prov_eff[idx$prov[u]] + dist_eff[d]
    a_base <- qlogis(cfg$aware0[[st]]) + dist_aw[d]
    prev[u, ]  <- plogis(p_base) * exp(-cfg$prev_decline * tt)   # incidence falling
    aware[u, ] <- plogis(a_base + cfg$aware_gain * tt)            # awareness rising
  }
  ## estimand: positivity among the undiagnosed, P(HIV+ | not yet diagnosed) = p(1-a) / (1 - p a)
  undiag <- prev * (1 - aware) / (1 - prev * aware)   # undiagnosed positivity theta
  theta  <- qlogis(pmin(pmax(undiag, 1e-5), 1 - 1e-5))

  ## --- selection offset lambda = stratum baseline + scenario dynamics ------
  lam_bar  <- mean(cfg$lambda0)
  lam_str  <- lam_bar + (cfg$lambda0[idx$stratum] - lam_bar) * lambda_stratum_scale
  lam_base <- lam_str + rnorm(D, 0, lambda_dist_sd)[idx$d]
  if (lambda_prov_sd > 0) lam_base <- lam_base + rnorm(G, 0, lambda_prov_sd)[idx$prov]
  lambda   <- matrix(lam_base, U, T) +
              lambda_dynamics(cfg$scenarios[[scenario]], U, T)

  ## --- routine positivity (register), logit scale --------------------------
  z <- theta + lambda + matrix(rnorm(U * T, 0, sqrt(cfg$v_rhis)), U, T)

  pop_u <- cfg$pop_share[idx$stratum]          # relative population per cell (equal district size)

  list(U = U, D = D, S = S, T = T, G = G, idx = idx, scenario = scenario,
       prov_eff = prov_eff, prev = prev, aware = aware, undiag = undiag,
       theta = theta, lambda = lambda, z = z, pop = as.numeric(pop_u))
}

## ---- survey observation given a DISTRICT allocation nmat (D x T) ----------
## A surveyed district observes ALL its strata; per-stratum logit-scale
## sampling variance ~ deff / (n_per * pi * (1 - pi)).
observe_survey <- function(pop, nmat_d, cfg, seed = NULL) {
  if (!is.null(seed)) set.seed(seed)
  U <- pop$U; T <- pop$T
  nmat_u <- nmat_d[pop$idx$d, , drop = FALSE]         # expand district -> units
  pic <- pmin(pmax(pop$undiag, 1e-4), 1 - 1e-4)
  psi <- cfg$deff / (nmat_u * pic * (1 - pic))
  psi[nmat_u == 0] <- NA
  Z <- pop$theta + matrix(rnorm(U * T), U, T) * sqrt(psi)
  Z[nmat_u == 0] <- NA
  list(Z = Z, psi = psi, n_d = nmat_d, n_u = nmat_u)
}
